        val cl = input.substring(0, if (space == -1) input.length else space)
        input = if (space == -1) Tuils.EMPTYSTRING else input.substring(space + 1)

        try {
            Color.parseColor(cl)
            return ArgInfo(cl, input, true, 1)
        } catch (e: Exception) {
            return ArgInfo(null, input, false, 0)
